#!/usr/bin/env python3
"""Build the GitHub Pages site. Standard library only; source data stays local."""
from pathlib import Path
from html import escape as esc
from decimal import Decimal, ROUND_HALF_UP
import json, os, re, hashlib, base64
from urllib.parse import urlsplit
ROOT = Path(__file__).resolve().parents[1]
DIMS = json.loads((ROOT/'data/image-dimensions.json').read_text())
C = json.loads((ROOT/'data/site.json').read_text())
SHEET_PAGES = json.loads((ROOT/'data/sheet-pages.json').read_text())
Y = json.loads((ROOT/'data/years.json').read_text())
P = json.loads((ROOT/'data/gumroad-products.json').read_text())['makeitdo']
RECIPES = json.loads((ROOT/'data/recipes.json').read_text())
ORIGIN = C['origin']
CONTACT = C['contact']
SOURCES = {
 'food': ('Historical Statistics of the United States, Part 1, p. 213, series E 187–202', 'https://fraser.stlouisfed.org/files/docs/publications/histstatus/hstat1970_cen_1975_v1.pdf'),
 'gas': ('EIA, Annual Energy Review, table 5.24: regular gasoline, nominal prices', 'https://www.eia.gov/totalenergy/data/annual/showtext.php?t=ptb0524'),
 'stamp': ('USPS, Rates for Domestic Letters Since 1863', 'https://about.usps.com/who/profile/history/domestic-letter-rates-since-1863.htm'),
 'wage': ('Department of Labor, History of Federal Minimum Wage Rates', 'https://www.dol.gov/agencies/whd/minimum-wage/history/chart'),
 'names': ('Social Security Administration, Popular Baby Names', 'https://www.ssa.gov/oact/babynames/decades/names1950s.html'),
 'bls': ('BLS Average Price Data: 2025 monthly observations', 'https://www.bls.gov/charts/consumer-price-index/consumer-price-index-average-price-data.htm'),
 'cpi': ('BLS Consumer Price Index, series CUUR0000SA0', 'https://data.bls.gov/timeseries/CUUR0000SA0'),
 'stamp26': ('USPS, Forever stamps: 82¢, checked November 5, 2026', 'https://store.usps.com/store/stamps/0-82/_/N-1pz9hus'),
 'film1': ('A Word to the Wives (1955), promotional film, Prelinger Archives', 'https://archive.org/details/Wordtoth1955'),
 'film2': ('Shopping Can Be Fun (1957), promotional film, Prelinger Archives', 'https://archive.org/details/Shopping1957'),
 'recipes': ('USDA, Family Fare (1950), Home and Garden Bulletin No. 1', 'https://archive.org/details/familyfarefoodma00unit')
}

# Infrastructure configuration is separate from editorial content and never embeds API secrets.
EMAIL = C.get('email_capture', {})
EXP = C.get('experiment', {})
if C['posthog_host'] not in {'https://us.i.posthog.com','https://eu.i.posthog.com'}:
 raise ValueError('PostHog must use its regional cloud ingest host')
if EMAIL.get('enabled'):
 u = urlsplit(EMAIL.get('form_action',''))
 if not (u.scheme=='https' and u.hostname and u.hostname.endswith('.sibforms.com') and u.path.startswith('/serve/') and not u.query and not u.fragment and not u.username and u.port is None):
  raise ValueError('Copy the HTTPS /serve/ action from the Brevo Simple HTML form')
 if EMAIL.get('double_opt_in_verified') is not True:
  raise ValueError('Verify Brevo double confirmation before enabling signup')
if EXP.get('enabled') and not C['posthog_project_key']:
 raise ValueError('Experiments require the public PostHog project key')
if not re.fullmatch(r'[a-z0-9-]{1,80}',EXP.get('key','launch-presentation-v1')): raise ValueError('Experiment key must be a short slug')
if set(EXP.get('variants',{})) != {'control','variant'}: raise ValueError('Experiments need control and variant entries')
for v in EXP.get('variants',{}).values():
 if set(v)-{'headline','hero','price'}: raise ValueError('Unknown experiment slot')
 if 'hero' in v and not (isinstance(v['hero'],dict) and v['hero'].get('alt') and re.fullmatch(r'[-a-zA-Z0-9_.]+\.(webp|png|jpg)',v['hero'].get('src','')) and (ROOT/('assets/img/'+v['hero']['src'])).is_file()): raise ValueError('Hero needs a local licensed src and descriptive alt')

def signup():
 if not EMAIL.get('enabled'): return ''
 return f'''<section class="section reading" aria-labelledby="signup-title"><h2 id="signup-title">Email updates</h2><form class="email-signup" action="{esc(EMAIL['form_action'],quote=True)}" method="post"><label for="signup-email">Email address</label><input id="signup-email" name="EMAIL" type="email" autocomplete="email" required aria-describedby="signup-note"><label class="email-consent"><input type="checkbox" name="OPT_IN" value="1" required> Send me Make It Do email updates. I can unsubscribe at any time.</label><div class="signup-trap" aria-hidden="true"><label for="email-address-check">Leave this blank</label><input id="email-address-check" name="email_address_check" tabindex="-1" autocomplete="off"></div><input type="hidden" name="locale" value="en"><input type="hidden" name="html_type" value="simple"><button class="button" type="submit">Send confirmation email</button><p id="signup-note" class="small">Brevo will email a confirmation link. You are subscribed only after confirming. Read our <a href="/privacy.html">privacy policy</a>. Free downloads remain available without email.</p></form></section>'''


def a(href,label,cls='',extra=''):
 return f'<a href="{esc(href,quote=True)}"'+(f' class="{cls}"' if cls else '')+f' {extra}>{label}</a>'
def src(key):
 title,url=SOURCES[key]; return a(url,esc(title))
def money(v):
 if v is None: return '—'
 v=Decimal(str(v)).quantize(Decimal('.01'),rounding=ROUND_HALF_UP)
 return f'{int(v*100)}¢' if v<1 else f'${v:,.2f}'
def exact(v):
 if v>=1: return money(v)
 n=Decimal(str(v*100)).quantize(Decimal('.1'),rounding=ROUND_HALF_UP)
 return f'{n.normalize():f}¢'
def row(year,key): return next((r for r in Y[str(year)]['rows'] if r['key']==key),None)
def img(name,alt,cls='',lazy=True):
 w,h=DIMS[name]
 variant=name.rsplit('.',1)[0]+'-500.webp'
 responsive=(f' srcset="/assets/img/{variant} 500w, /assets/img/{name} {w}w" sizes="(max-width:680px) 250px, 320px"' if variant in DIMS else '')
 return f'<img src="/assets/img/{name}"'+responsive+f' alt="{esc(alt)}" width="{w}" height="{h}" class="{cls}" '+('loading="lazy"' if lazy else 'fetchpriority="high"')+' decoding="async">'

def yearform(label='What year were you born?',button='Find my year',default='',ident='year'):
 return f'''<form class="year-form" action="/year/" method="get"><label for="{ident}">{label}</label><div class="year-entry"><input id="{ident}" name="year" type="text" inputmode="numeric" pattern="(?:19)?[0-9]{{2}}" minlength="2" maxlength="4" placeholder="e.g. 1953" value="{default}" required aria-describedby="{ident}-hint"><button class="button" type="submit">{button} <span aria-hidden="true">→</span></button></div><p id="{ident}-hint" class="small">1930–1975 · Free to see and print · No email needed</p><p class="form-error" role="alert" hidden></p></form>'''
def checkout(key,label,year=None):
 product=P[key]
 enabled=C['free_email_enabled'] if key.startswith('free') else C['commerce_enabled']
 if enabled:
  from urllib.parse import urlencode
  query={'wanted':'true'}
  if year and str(year) in product.get('variants',{}): query['variant']=str(year)
  href=product['url']+'?'+urlencode(query)
  return a(href,label,'button',f'data-checkout="{key}" data-year="{year or ""}"')
 return '<p class="availability"><span class="status-dot" aria-hidden="true"></span> '+('Email delivery opens with the film. Download it here now.' if key.startswith('free') else 'Ordering opens with the film. No payment is being taken yet.')+'</p>'
def offer(year=1953,full=False):
 year=int(year)
 return f'''<section class="offer section" id="book"><div class="book-display"><a href="/downloads/your-year-1953-sample.pdf" data-event="sample_opened">{img(f'book-{year}.webp',f'Digital cover preview for the {year} Your Year, in Color booklet',lazy=not full)}</a><p class="small">Digital cover preview · Historical footage is dated inside.</p></div><div class="offer-copy"><p class="eyebrow">A little history. A very personal gift.</p><h2>{'Your Year' if full else year if year != 1953 else 'Their year'},<br><em>in Color.</em></h2><p class="lede">The world they were born into, in a booklet they can hold.</p><p>A 20-page keepsake with their first name on the cover. Real prices, popular baby names, two period recipes, color film frames, and room for the memories only they can add.</p><ul class="check-list"><li>Large print, with 16-point body text</li><li>Printed booklet + a digital PDF copy</li><li>Birth years 1930–1970</li></ul><p class="price">$49 <span>U.S. shipping included<br>Applicable tax shown at checkout</span></p><div class="actions">{a(f'/your-year/?year={year}#order','Choose a year & see the booklet','button')}{a('/your-year/#inside','Look inside','text-link')}</div>{'<p class="small">Choose the birth year below. Cover shown is a 1953 sample.</p>' if full else '<p class="small">Ordering opens with the film. Preview the real pages now.</p>'}</div></section>'''
def crumbs(items):
 return '<nav class="breadcrumbs" aria-label="Breadcrumb">'+a('/','Home')+''.join(' <span aria-hidden="true">/</span> '+(a(h,l) if h else f'<span>{l}</span>') for l,h in items)+'</nav>'
PAGES=[]
def page(path,title,description,body,kind='WebPage',schema=None,noindex=False,sticky=False,canonical=None,scripts=()):
 url=ORIGIN+(canonical or path)
 nodes=[{'@type':'Organization','@id':ORIGIN+'/#organization','name':'Make It Do','url':ORIGIN+'/','email':CONTACT,'sameAs':['https://www.youtube.com/@makeitdo']},{'@type':'WebSite','@id':ORIGIN+'/#website','name':'Make It Do','url':ORIGIN+'/'},{'@type':kind,'@id':url+'#page','url':url,'name':title,'description':description,'inLanguage':'en-US','isPartOf':{'@id':ORIGIN+'/#website'},'publisher':{'@id':ORIGIN+'/#organization'}}]
 if schema: nodes.extend(schema)
 if path not in ['/', '/404.html']:
  nodes.append({'@type':'BreadcrumbList','itemListElement':[{'@type':'ListItem','position':1,'name':'Home','item':ORIGIN+'/'},{'@type':'ListItem','position':2,'name':title,'item':url}]})
 if path=='/':
  body=body.replace('<h1>','<h1 data-ab-slot="headline">',1).replace('<img src="/assets/img/kitchen-1955-c.webp"','<img data-ab-slot="hero" src="/assets/img/kitchen-1955-c.webp"',1).replace('<p class="price">$49 ', '<p class="price"><span class="price-value" data-ab-slot="price">$49</span> ',1)
 cfg={'origin':ORIGIN,'film':C['film'],'posthog_host':C['posthog_host'],'posthog_project_key':C['posthog_project_key'],'experiment':EXP if path=='/' else {'enabled':False}}
 experiment_script='<script '+('' if cfg['experiment'].get('enabled') else 'defer ')+'src="/assets/experiments.js"></script>'
 config_json=json.dumps(cfg).replace('<','\\u003c')
 schema_json=json.dumps({'@context':'https://schema.org','@graph':nodes},ensure_ascii=False).replace('<','\\u003c')
 hashes=['\"sha256-'+base64.b64encode(hashlib.sha256(x.encode()).digest()).decode()+'\"' for x in [config_json,schema_json]]
 # Quotes around CSP hashes must be single quotes; no unsafe-inline/eval or remote script.
 script_hashes=' '.join(h.replace('"',"'") for h in hashes)
 api_origin=(lambda u:(u.scheme+'://'+u.netloc) if u.netloc else '')(urlsplit(C.get('orders_api') or ''))
 connect="'self'"+(' '+C['posthog_host'] if C['posthog_project_key'] else '')+(' '+api_origin if api_origin else '')
 forms="'self'"+(' '+urlsplit(EMAIL['form_action']).scheme+'://'+urlsplit(EMAIL['form_action']).netloc if EMAIL.get('enabled') else '')+(' '+api_origin if api_origin else '')+''.join(' '+o for o in C.get('checkout_origins',[]) if re.fullmatch(r'https://[a-z0-9.-]+|http://127\.0\.0\.1:\d+',o))
 # form-action also governs the redirect after a form post: the checkout's own origin must be listed or the browser stops at our page
 csp=f"default-src 'none'; script-src 'self' {script_hashes}; style-src 'self'; img-src 'self'; media-src 'self'; font-src 'self'; connect-src {connect}; form-action {forms}; base-uri 'none'; object-src 'none'"
 consent=('<aside id="analytics-choice" class="analytics-choice" aria-label="Optional visit analytics"><p>Allow visit analytics? This helps us understand which film links and pages work. Downloads work either way.</p><div class="actions"><button type="button" class="button secondary" data-consent="no">Decline</button><button type="button" class="button secondary" data-consent="yes">Allow analytics</button><a href="/privacy.html">Privacy details</a></div></aside>').replace('id="analytics-choice"', 'id="analytics-choice"'+(' hidden' if not C['posthog_project_key'] else ''))

 extra_scripts=''.join(f'<script defer src="{x}"></script>' for x in scripts)
 html=f'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta http-equiv="Content-Security-Policy" content="{esc(csp,quote=True)}"><meta name="referrer" content="strict-origin-when-cross-origin"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="theme-color" content="#234638"><title>{esc(title)} · Make It Do</title><meta name="description" content="{esc(description,quote=True)}"><link rel="canonical" href="{url}"><meta name="robots" content="{'noindex,follow' if noindex else 'index,follow,max-image-preview:large'}"><meta property="og:type" content="website"><meta property="og:site_name" content="Make It Do"><meta property="og:title" content="{esc(title,quote=True)}"><meta property="og:description" content="{esc(description,quote=True)}"><meta property="og:url" content="{url}"><meta property="og:image" content="{ORIGIN}/assets/img/kitchen-1955-c.webp"><meta property="og:image:width" content="1280"><meta property="og:image:height" content="960"><meta name="twitter:card" content="summary_large_image"><link rel="icon" href="/assets/favicon.svg" type="image/svg+xml"><link rel="preload" href="/assets/fonts/sourceserif4-display.woff2" as="font" type="font/woff2" crossorigin><link rel="stylesheet" href="/assets/site.css"><script id="site-config" type="application/json">{config_json}</script><script type="application/ld+json">{schema_json}</script>{experiment_script}<script defer src="/assets/site.js"></script>{extra_scripts}</head><body>
<a class="skip" href="#main">Skip to content</a><div class="topline">{esc(C.get("banner","Every number has a source. Every cover has a name."))}</div><header class="masthead wrap"><a class="wordmark" href="/" aria-label="Make It Do home">Make It Do<span class="brand-dot">.</span></a><nav aria-label="Main navigation">{a('/year/','Find your year')}{a('/1950s-life/','Life in the ’50s')}{a('/gifts/','Gifts for parents')}{a('/shop/','Shop')}{a('/your-year/','The booklet','nav-order')}</nav></header>{consent}<main id="main" class="wrap">{body}{signup() if path=='/' else ''}</main>
<footer class="footer"><div class="wrap footer-grid"><div><a class="wordmark" href="/">Make It Do<span class="brand-dot">.</span></a><p>Real color film. The records people kept.<br>The ordinary days worth remembering.</p><p class="small">© 2026 Make It Do</p></div><nav aria-label="Explore">{a('/year/','Prices by year')}{a('/your-year/','Your Year, in Color')}{a('/kitchen/','Free recipe cards')}{a('/sources/','Our sources & method')}</nav><nav aria-label="Help">{a('/about/','About Make It Do')}{a('/accessibility/','Accessibility')}{a('/privacy.html','Privacy & analytics choices')}{a('/terms.html','Terms & order information')}{a('mailto:'+CONTACT,'Contact us')}{a('https://www.youtube.com/@makeitdo','Watch on YouTube ↗')}</nav></div></footer>{'<aside class="mobile-bar" aria-label="Your year"><span>Your Year, in Color · $49</span>'+a('#book','See the booklet','button')+'</aside>' if sticky else ''}</body></html>'''
 target=ROOT/(path.lstrip('/') if path.endswith('.html') else path.strip('/')+'/index.html') if path!='/' else ROOT/'index.html'
 target.parent.mkdir(parents=True,exist_ok=True); target.write_text(html)
 if not noindex and canonical is None: PAGES.append(path)

def directory():
 return '<div class="year-directory">'+''.join(f'<section><h3>{start}s</h3><div class="year-links">'+''.join(a(f'/{y}/',str(y)) for y in range(max(1930,start),min(start+10,1976)))+'</div></section>' for start in range(1930,1980,10))+'</div>'

home=f'''<section class="home-hero"><div class="hero-copy"><p class="eyebrow"><span class="status-dot" aria-hidden="true"></span> Everyday America, in real color</p><h1>The past was<br>never black<br><em>& white.</em></h1><p class="lede">Neither were the days you remember.</p><p>Step back into the kitchens, corner stores, and ordinary lives of another America. Then find a little piece of your own.</p>{yearform()}</div><figure class="hero-film"><div class="film-top"><span>FROM THE ARCHIVE</span><span>1955 / COLOR</span></div>{img('kitchen-1955-c.webp','A peach and turquoise American kitchen from the 1955 film A Word to the Wives',lazy=False)}<span class="frame-label" aria-hidden="true">A WINDOW INTO EVERYDAY AMERICA</span><figcaption>A kitchen in 1955. The colors were there all along.<span><cite>A Word to the Wives</cite> · A promotional film, not a recreation.</span></figcaption></figure></section>
<div class="provenance-strip"><span>Real film from the time</span><span>Prices from government records</span><span>Made for your family</span></div>
<section class="section ledger-teaser"><div><p class="eyebrow">A little perspective from 1953</p><h2>Remember what<br>a dollar could do?</h2><p>A dozen eggs. A gallon of gas. The small things that bring a whole world back.</p>{a('/1953/','See all the 1953 prices →','text-link')}<p class="small">U.S. averages, rounded to the nearest cent.<br>{src('food')}; {src('gas')}.</p></div><div class="receipt"><div class="receipt-title"><span>THE EVERYDAY LEDGER</span><b>1953</b></div><dl><div><dt>White bread <small>one pound</small></dt><dd>16¢</dd></div><div><dt>Eggs <small>one dozen</small></dt><dd>70¢</dd></div><div><dt>Gasoline <small>one gallon</small></dt><dd>29¢</dd></div></dl><p>Small prices. A different paycheck, too.</p></div></section>
{offer()}
<section class="section stories"><div class="section-heading"><div><p class="eyebrow">Stay a little longer</p><h2>There’s a story in the everyday.</h2></div>{a('/1950s-life/','Explore the 1950s →','text-link')}</div><div class="story-grid"><article>{a('/1950s-life/',img('cars-1957-b.webp','A parking lot full of 1950s American cars'))}<p class="eyebrow">On Main Street</p><h3>{a('/1950s-life/','The America between the headlines')}</h3><p>What real color film can tell us, and what the camera leaves out.</p></article><article>{a('/kitchen/',img('kitchen-1955-b.webp','Coffee at a kitchen table in a 1955 promotional film'))}<p class="eyebrow">At the kitchen table</p><h3>{a('/kitchen/','Three recipes from 1950, on the house')}</h3><p>Meat loaf, upside-down cake, and brownies. Free cards from the USDA’s own cookbook.</p></article></div></section>'''
page('/','What things cost the year you were born','Look up U.S. prices for 1930–1975, download your free birth-year sheet, and preview Your Year, in Color, a personalized $49 keepsake.',home)
page('/year/','What did things cost the year you were born?','Free U.S. birth-year price sheets for 1930–1975. Browse government-record prices, baby names, and a printable sheet with no email needed.',crumbs([('Find your year',None)])+'<section class="page-intro"><p class="eyebrow">Your own little piece of history</p><h1>Every year has a story.<br><em>Start with yours.</em></h1><p class="lede">The price of bread. The names in the nursery. The world the year you arrived.</p>'+yearform(ident='year-picker')+'</section><section class="section"><h2>Or choose a year</h2><p>Full food-price records through 1970. The 1971–1975 sheets contain the records available, with gaps marked.</p>'+directory()+'</section>')

for year,d in Y.items():
 y=int(year); full=y<=1970
 rows=d['rows']; keys={r['key']:r for r in rows}; mw=keys.get('minwage',{}).get('then')
 first=[r for r in rows if r['key'] in ['E188','E194','gasoline_regular_retail','postage_first_class_letter']]
 answer=f'In {year}, '+', '.join(f'{r["label"].lower()} cost {exact(r["then"])}' for r in first)+'.'
 table='<div class="table-wrap" tabindex="0" role="region" aria-label="Historical price comparison"><table class="price-table"><caption>U.S. prices in '+year+' and the dated comparison</caption><thead><tr><th scope="col">The everyday things</th><th scope="col">'+year+'</th><th scope="col">Reference price</th></tr></thead><tbody>'
 for r in rows:
  label='A pound of white bread' if r['key']=='E188' else r['label']
  reference='2026 stamp' if r['key']=='postage_first_class_letter' else '2025 average' if r['key']!='minwage' else 'Federal rate, 2026'
  if r['now'] is None: reference='Not compared'
  table+=f'<tr><th scope="row">{esc(label)}<small>{esc(r["unit"])}</small></th><td class="then-price">{exact(r["then"])}</td><td>{money(r["now"])}<small>{reference}</small></td></tr>'
 table+='</tbody></table></div>'
 partial='' if full else '<p class="notice">A partial record: our verified food-price table ends in 1970. This page and its free sheet show only the available gas, postage, pay, and housing records. We do not offer a booklet for this year.</p>'
 work=''
 if mw:
  chosen=keys.get('E194',keys.get('gasoline_regular_retail'))
  if chosen:
   mins=int(Decimal(str(chosen['then']/mw*60)).quantize(Decimal('1'),rounding=ROUND_HALF_UP))
   work=f'<section class="context-panel"><p class="eyebrow">The paycheck matters</p><h2>Was it really cheaper in {year}?</h2><p>{esc(chosen["label"])} cost {exact(chosen["then"])}. At the {money(mw)} federal hourly minimum used here, that took about <strong>{mins} minutes of work</strong>, before tax.</p><p class="small">Calculation: price ÷ hourly wage × 60, using unrounded prices. The rate is the last federal rate effective that year, not an annual average; coverage varied. Federal minimum pay does not describe every worker’s earnings or buying power. {src("wage")}.</p></section>'
 else: work='<section class="context-panel"><h2>Prices alone cannot tell us what was affordable.</h2><p>There was no federal minimum wage before 1938, so we do not invent a minutes-of-work comparison for this year.</p></section>'
 names=d['names']; nameblock=''
 if names:
  nameblock=f'<section class="section names"><p class="eyebrow">The names in the nursery</p><h2>Hello, {names["girls"][0]}. Hello, {names["boys"][0]}.</h2><div class="two-col"><div><h3>Girls born in {year}</h3><p>'+', '.join(names['girls'])+f'.</p></div><div><h3>Boys born in {year}</h3><p>'+', '.join(names['boys'])+f'.</p></div></div><p class="small">Social Security applications for U.S. births in {year}. Counts and spelling come from the national annual file. {a("https://www.ssa.gov/oact/babynames/limits.html","SSA national data and method")}.</p></section>'
 get=f'<div class="download-panel" id="sheet"><div><p class="eyebrow">Yours, on the house</p><h2>The {year} sheet, ready to print.</h2><p>{SHEET_PAGES[year]} pages in large print, with space to write what it cost in your house.</p></div><div>{a(f"/downloads/what-things-cost-{year}.pdf",f"Download my {year} sheet ↓","button",f"download data-download=\"free_sheet\" data-year=\"{year}\"")}<p class="small">Free PDF · No email or card needed</p>{checkout("free_sheet",f"Email me the {year} sheet",year)}</div></div>'
 sourcelist='<section class="section source-section" id="sources"><p class="eyebrow">The record behind the memory</p><h2>Where the numbers come from</h2><p>Food and gas comparisons use the supplied 2025 BLS averages. Postage is 82¢ in November 2026. These are dated reference prices, not a live price feed. Milk then was home-delivered; the reference is store-bought. Fuel, products, and coverage have changed.</p><ul>'+''.join(f'<li>{src(k)}</li>' for k in ['food','gas','stamp','wage','bls','stamp26','cpi'])+'</ul><details><summary>See the exact series for each figure</summary><ul>'+''.join('<li><b>'+esc(r['label'])+':</b> '+esc(r['src'])+('<br>Comparison: '+esc(r['now_src']) if r.get('now_src') else '')+'</li>' for r in rows)+'</ul></details><p class="small">Bread is priced by the pound, not by an assumed loaf size. Original averages may include tenths of a cent. The printable sheet rounds to whole cents. CPI comparison: $1 in '+year+' had approximately the buying power of $'+str(d['multiplier'])+' in 2025; this is a general index, not a family budget. '+a('/sources/','Our editorial method and corrections')+'.</p></section>'
 previous=a(f'/{y-1}/',f'← {y-1}') if y>1930 else a('/year/','All years')
 nxt=a(f'/{y+1}/',f'{y+1} →') if y<1975 else a('/year/','All years')
 body=crumbs([('Prices by year','/year/'),(year,None)])+f'<section class="year-hero"><div><p class="eyebrow">The year you were born</p><h1 class="year-number">{year}<span class="brand-dot">.</span></h1><h2>What did things cost?</h2><p class="lede">{answer}</p><p>From U.S. government records. A national average, not a promise about every store.</p><div class="actions">{a("#sheet","Get my free sheet","button")}{a("#book","See the $49 booklet","text-link") if full else ""}</div></div><figure class="year-photo">{img("market-1957-b.webp","The meat counter at Hillsdale Shopping Center, San Mateo, California, in 1957",lazy=False)}<figcaption>A glimpse of the decade: <cite>Shopping Can Be Fun</cite> (1957). This frame is not a photograph of {year}.</figcaption></figure></section>'+partial+f'<section class="section"><div class="section-heading"><div><p class="eyebrow">The everyday ledger</p><h2>A shopping list from {year}.</h2></div>{a("#sources","Check the sources ↓","text-link")}</div>'+table+'</section>'+get+work+(offer(y) if full else '')+nameblock+sourcelist+f'<nav class="year-pagination" aria-label="Other years">{previous}{a("/year/","Choose another year")}{nxt}</nav>'
 schema=[{'@type':'Dataset','name':f'U.S. everyday prices in {year}','description':answer,'url':ORIGIN+f'/{year}/#sources','creator':{'@id':ORIGIN+'/#organization'},'temporalCoverage':year,'spatialCoverage':'United States','isBasedOn':[SOURCES[k][1] for k in ['food','gas','stamp','wage']],'distribution':{'@type':'DataDownload','encodingFormat':'application/json','contentUrl':ORIGIN+'/data/years.json'}}]
 page(f'/{year}/',f'{year} prices: bread, eggs, gas & everyday life',answer+' Free printable birth-year sheet, sources, and wage context.',body,schema=schema,sticky=full)

inside='<section class="section" id="inside"><p class="eyebrow">Look inside before you decide</p><h2>Real pages. Room for their stories.</h2><p>A few pages from the 1953 edition: the prices, the names, and the questions you can ask together.</p><div class="sample-grid">'+''.join(f'<figure>{img(f"sample-{i}.webp",alt)}<figcaption>{caption}</figcaption></figure>' for i,alt,caption in [(2,'The grocery price page in the actual 1953 booklet','The kitchen ledger'),(7,'Baby names with counts in the actual 1953 booklet','The names in the nursery'),(14,'The family questions page in the actual 1953 booklet','The questions that start a conversation')])+'</div>'+a('/downloads/your-year-1953-sample.pdf','Open the four-page sample PDF ↓','button secondary','data-event="sample_opened"')+'</section>'
order=f'<section class="section order-panel" id="order"><p class="eyebrow">Your Year, in Color · $49</p><h2>Whose year will you bring back?</h2><p>Choose a birth year from 1930–1970. You will enter the first name for the cover and the U.S. mailing address in Gumroad when ordering opens.</p><form id="book-form"><label for="book-year">Birth year</label><select id="book-year" name="year">'+''.join(f'<option value="{y}"'+(' selected' if y==1953 else '')+f'>{y}</option>' for y in range(1930,1971))+'</select>'+checkout('youryear','Continue to Gumroad — $49',1953)+'</form><p>One purchase, one printed booklet, and a PDF. U.S. shipping included; applicable tax appears at checkout. No subscription.</p><p class="small">Production and delivery dates will be confirmed when ordering opens. We cannot promise arrival by a holiday. Questions? '+a('mailto:'+CONTACT,'Email Make It Do')+'.</p></section>'
product_schema=[{'@type':'Product','name':'Your Year, in Color','description':'20-page personalized large-print birth-year booklet with a printed copy and PDF, for 1930–1970. Ordering opens with the film.','image':ORIGIN+'/assets/img/book-1953.webp','brand':{'@type':'Brand','name':'Make It Do'},'offers':{'@type':'Offer','url':ORIGIN+'/your-year/#order','price':'49.00','priceCurrency':'USD','availability':'https://schema.org/InStock' if C['commerce_enabled'] else 'https://schema.org/OutOfStock','seller':{'@id':ORIGIN+'/#organization'}}}]
faq='<section class="section reading"><h2>A few practical questions</h2><details><summary>Can I give this to Mom or Dad?</summary><p>Yes. Use their first name for the cover and their birth year. When ordering opens, you can have the printed copy sent to their U.S. address. The buyer receives the PDF.</p></details><details><summary>Are all the pictures from the chosen year?</summary><p>No. The prices and names are specific to the year. Color film frames show everyday life in the period and carry the actual film’s title and date. They are not presented as family photographs.</p></details><details><summary>Does my parent need to use an app?</summary><p>The printed booklet can be enjoyed without a phone, account, or app. The digital PDF opens in a standard PDF reader.</p></details><details><summary>What if the book arrives damaged or a detail is wrong?</summary><p>Write to '+a('mailto:'+CONTACT,CONTACT)+'. We will work with you to correct the problem. '+a('/terms.html','Read our order terms')+'.</p></details></section>'
import sys as _sys; _sys.path.insert(0,str(ROOT/'scripts')); import store_pages
store_pages.build(page,a,crumbs,Y,C,json.loads((ROOT/'store/catalog.json').read_text()))
gift=f'''{crumbs([('Gifts for parents',None)])}<section class="page-intro reading"><p class="eyebrow">For the parent who says “I don’t need anything”</p><h1>Give them their year.<br><em>Make room for their stories.</em></h1><p class="lede">A gift for Mom or Dad that starts with the world they were born into, and ends with a conversation.</p><p>They open a booklet with their name on the cover. You ask what groceries cost in their house. A number on the page becomes a story you haven’t heard before.</p>{a('/your-year/#order','See Your Year, in Color — $49','button')}</section>{inside}<section class="section reading"><h2>A gift without homework.</h2><p>The 20-page booklet is ready to read. There is no weekly assignment and no app for your parent to learn. Prices, popular names, period recipes, and real film frames are already there. The blank spaces are an invitation.</p><ol class="steps"><li><h3>Choose their birth year</h3><p>1930–1970, with prices and names taken from the records.</p></li><li><h3>Put their first name on the cover</h3><p>The details are entered at checkout when ordering opens.</p></li><li><h3>Sit down with them</h3><p>“Who did the shopping in your house?” is a good place to start.</p></li></ol><p><b>$49, U.S. shipping included.</b> Applicable tax is shown at checkout. Ordering opens with the film; no holiday delivery date is promised.</p>{a('/your-year/#order','Choose their year','button')}{a('/year/','Start with a free year sheet','text-link')}</section>'''
page('/gifts/','A birth-year gift for Mom or Dad','Give a parent their birth year in a personalized, large-print $49 booklet. Real prices, names, recipes, and room for family stories. Preview real pages.',gift)

life=f'''{crumbs([('Everyday life in the 1950s',None)])}<article><header class="page-intro reading"><p class="eyebrow">The world behind the film</p><h1>Everyday life in<br><em>1950s America.</em></h1><p class="lede">The kitchen, the supermarket, the car park. Ordinary places look different when you see them in their original colors.</p><p>Our film, <cite>{C['film_title']}</cite>, begins with footage made at the time. Here is how to read those pictures alongside the records.</p></header><figure class="wide-film">{img('cars-1957-b.webp','American cars at Hillsdale Shopping Center in San Mateo in the 1957 film Shopping Can Be Fun',lazy=False)}<figcaption>Hillsdale Shopping Center, San Mateo, California. <cite>Shopping Can Be Fun</cite> (1957), a promotional film.</figcaption></figure><div class="reading section"><h2>What did groceries cost in the 1950s?</h2><p>In 1953, a pound of white bread averaged 16.4¢, a dozen eggs 69.8¢, and half a gallon of delivered milk 46.8¢ in the federal retail-price series. Regular gasoline averaged 28.7¢ a gallon.</p><p>Those small prices came with different wages. The federal minimum was 75¢ an hour in 1953, for workers covered by it. Eggs therefore took about 56 minutes of work at that rate, before taxes. It is a useful comparison, not a complete account of affordability.</p><p>{src('food')}; {src('gas')}; {src('wage')}.</p>{a('/1953/','See the full 1953 ledger →','text-link')}<h2>The kitchen on film was also a sales pitch.</h2><p><cite>A Word to the Wives</cite> (1955) shows a kitchen in peach and turquoise, appliances, and a carefully staged household. It is color footage from the period, but it is also a promotional film: evidence of what companies wanted families to want.</p><p>We keep the original title and date with each frame. A scene from 1955 does not become a scene from someone’s birth year just because it appears in their booklet.</p><p>{src('film1')}.</p><h2>A supermarket, and the world outside its frame.</h2><p><cite>Shopping Can Be Fun</cite> (1957) takes the camera to Hillsdale Shopping Center. Its meat counter and parking lot give us details that a black-and-white price table cannot: lettering on signs, clothing, colors, and the arrangement of the store.</p><p>A promotional camera gives us a selected view. It cannot stand for every American household, income, region, or experience. We use the records to check price claims and avoid turning an attractive scene into a claim that life was better for everybody.</p><p>{src('film2')}.</p><h2>What did families cook?</h2><p>The USDA’s 1950 <cite>Family Fare</cite> includes meat loaf, upside-down cake, and brownies. Our free recipe cards reproduce those three recipes from pages 34, 81, and 85. They show what a government kitchen recommended, not a survey of what every family ate.</p>{a('/kitchen/','Get the three free recipe cards →','text-link')}<h2>Find the year that belongs to your family.</h2><p>Our year pages cover 1930–1975. They give the answer first, with the source and its limits. The free sheet is yours to keep.</p>{yearform(ident='life-year')}</div></article>'''
page('/1950s-life/','Everyday life in 1950s America: prices, kitchens & real color film','What 1950s America looked like in original color film, what groceries cost, and what promotional footage leaves out. Government records and archive sources.',life,'WebPage',schema=[{'@type':'Article','headline':'Everyday life in 1950s America: prices, kitchens & real color film','author':{'@id':ORIGIN+'/#organization'},'publisher':{'@id':ORIGIN+'/#organization'},'dateModified':C['updated'],'mainEntityOfPage':ORIGIN+'/1950s-life/','image':ORIGIN+'/assets/img/cars-1957-b.webp'}])

kitchen=crumbs([('The 1950 kitchen',None)])+f'<section class="year-hero"><div><p class="eyebrow">From the government’s kitchen, 1950</p><h1>Something good<br><em>to come home to.</em></h1><p class="lede">Three free recipe cards from the USDA’s <cite>Family Fare</cite>.</p><p>Meat loaf, upside-down cake, and brownies, transcribed from the original pages. Large print, on 5-by-8-inch cards.</p>{a("/downloads/make-it-do-1950-recipe-cards.pdf","Download the three free cards ↓","button","download data-download=\"free_cards\"")}<p class="small">PDF · No email or card needed</p>{checkout("free_cards","Email me the free recipe cards")}</div><figure>{img("kitchen-1955-b.webp","Coffee in a 1955 kitchen, from A Word to the Wives",lazy=False)}<figcaption>A kitchen-table moment from <cite>A Word to the Wives</cite> (1955). The recipes themselves are from 1950.</figcaption></figure></section><div class="section recipe-list">'
for r in RECIPES:
 kitchen+=f'<article class="recipe"><p class="eyebrow">USDA · 1950 · Page {r["page"]}</p><h2>{esc(r["title"])}</h2><p>{esc(r.get("yield") or "")}</p><details><summary>Read the original recipe</summary><ul>'+''.join('<li>'+esc(t)+'</li>' for t in r['ingredients'])+'</ul>'+''.join('<p>'+esc(t)+'</p>' for t in r['method'])+a(r['source_url'],'Check the original page scan ↗')+'</details></article>'
kitchen+='</div><section class="section reading"><h2>Cookbook history, with its source attached.</h2><p>These are historical transcriptions, not modern recipe tests. We have not kitchen-tested them for this site. '+src('recipes')+'.</p><p>Checked against the page scans on November 4, 2026. The cards preserve the period wording; follow current food-handling guidance when cooking.</p>'+a('/year/','See what groceries cost in your year →','text-link')+'</section>'
page('/kitchen/','Free 1950 recipe cards: meat loaf, upside-down cake & brownies','Download three free large-print recipe cards, transcribed from the USDA’s 1950 Family Fare, with links to the original page scans. No signup required.',kitchen)

sources=crumbs([('Sources & method',None)])+'<article class="reading page-intro"><p class="eyebrow">A memory deserves a source</p><h1>The record behind<br><em>the everyday.</em></h1><p class="lede">We separate what the records say, what the film shows, and what a family remembers.</p><h2>Prices: a table, a year, a unit.</h2><p>The year pages use the supplied transcription of federal tables. Each page names the series behind every row. Food covers 1930–1970; later pages are partial. Prices are U.S. averages, not a local receipt. Historical bread is per pound; milk is half a gallon delivered. Modern milk is the store-bought comparison.</p><p>The reference column uses the supplied 2025 BLS averages, with a separately dated 2026 postage rate and federal wage rate. We do not describe these as live “today” prices. The original downloadable sheets use rounded cents and say “today”; read that column as this dated reference set.</p><h2>Minutes of work are a calculation, not a claim about every worker.</h2><p>Price ÷ last federal hourly minimum effective in the year × 60. The federal law did not cover every worker; rates and coverage could change during a year. There is no federal-wage comparison before 1938. The calculation uses the unrounded price and rounds only the answer.</p><h2>Names: the national annual file.</h2><p>The top ten female and male names come from Social Security’s national birth-year data. The booklet includes counts. These are application records, not a complete census of every birth.</p><h2>Film: real, dated, and selected.</h2><p>The reused frames come from <cite>A Word to the Wives</cite> (1955) and <cite>Shopping Can Be Fun</cite> (1957), promotional films held in the Prelinger Archives. They show period color footage, not someone’s private family album. Dates stay with the images. Any recreation added to our work must be labelled as a recreation.</p><h2>Read the primary sources</h2><ul>'+''.join('<li>'+src(k)+'</li>' for k in SOURCES)+'</ul><h2>Corrections</h2><p>Found an error? Send the year, the item, and the source to '+a('mailto:'+CONTACT,CONTACT)+'. We will check it against the record and correct the page and printable if needed.</p><p class="small">Page reviewed November 5, 2026. Make It Do is an independent film and keepsake project. No government agency endorses our products.</p></article>'
page('/sources/','Sources & method: how we check historical prices','The government tables, film archives, baby-name records, and calculation methods behind Make It Do’s birth-year sheets and booklets.',sources)
about=crumbs([('About',None)])+'<article class="reading page-intro"><p class="eyebrow">Make It Do</p><h1>Ordinary days.<br><em>Worth keeping.</em></h1><p class="lede">Films about everyday life in America, from the 1930s to the 1970s, told with real film and the records people kept.</p><p>The kitchen table. The price of a loaf. The story that starts when someone says, “I remember that.” Make It Do follows those small things back to their sources, and makes keepsakes that give families a place to add their own memories.</p><p>Watch '+a('https://www.youtube.com/@makeitdo','Make It Do on YouTube')+'. For questions, corrections, or orders, write to '+a('mailto:'+CONTACT,CONTACT)+'.</p><p>From the same small studio: '+a('https://www.youtube.com/@bibleasitwas','The Bible As It Was')+' and '+a('https://www.youtube.com/@largeprintTV','The Large Print')+'. Each channel sells under its own name.</p>'+a('/sources/','Read our sources & method →','text-link')+'</article>'
page('/about/','About Make It Do','Real color film and real records of everyday America, 1930s–1970s. Independent films, free birth-year price sheets, and personal keepsakes.',about)

privacy=crumbs([('Privacy',None)])+f'''<article class="reading page-intro"><h1>Privacy, in plain English.</h1><p>Make It Do, The Bible As It Was and The Large Print. Updated November 5, 2026.</p><h2>Your free sheet</h2><p>You can read the prices and download every free sheet and the recipe cards without giving us an email address. A direct download does not sign you up for email.</p><h2>Visit and film counts</h2><p>When configured, Make It Do uses PostHog to count page visits, year selections, downloads, sample opens, and checkout clicks. We send the page path, film number, entry door (spoken address, QR, or description), a random visit ID, and a referrer hostname or broad source category. We do not send email addresses, names, shipping addresses, payment details, or full referring URLs to analytics. Analytics providers may receive the IP address used to connect to them.</p><p>Optional visit analytics start only after you choose Allow analytics. Until then, no analytics identifier or attribution is stored and no analytics request is sent. With permission, sessionStorage keeps the entry door, campaign tags, random ID, and any experiment assignment during a visit. LocalStorage remembers your consent choice. You can withdraw permission here; this removes stored visit attribution. DNT and GPC override permission. Optional experiments follow the same choice. No advertising cookies, session recordings, heatmaps, fingerprinting, or automatic form capture are installed. We honor Global Privacy Control and Do Not Track. Counts are incomplete when tracking is blocked or declined.</p><button id="analytics-toggle" class="button secondary" type="button">Analytics choices</button><p id="analytics-status" role="status" class="small"></p><noscript><p>JavaScript is disabled, so our visit analytics do not run.</p></noscript><h2>Email updates</h2><p>Optional email signup, when enabled, uses Brevo to send a double confirmation link. Only confirming that link subscribes you to updates. Your email is sent directly to Brevo, never to visit analytics. Unsubscribe in any update. Downloading a free file is separate from marketing permission.</p><h2>Email and checkout</h2><p>When email delivery or ordering is enabled, you leave this site for Gumroad. Gumroad collects the email and any details needed to deliver the selected product. Choosing a free file here does not imply agreement to marketing. Marketing choices are presented at checkout; use the unsubscribe link in any marketing message or email us to stop it.</p><p>For printed products, the printer and shipping provider need the recipient’s name, delivery address, and product details. Our planned print setup uses Prodigi for booklets and standard hardcovers, with Lulu for the cloth Heirloom edition. Printed orders are not open yet. We do not see your card number. Gumroad handles payment, receipts, applicable taxes, and its refund process.</p><p>When the sales integration is configured, verified paid orders and completed free Gumroad signups with analytics permission carried from this site are counted in PostHog with film, door, product, year, currency, amount, and a pseudonymous event identifier. Customer emails and postal addresses are not sent. We do not sell your personal information or share it for advertising.</p><h2>Other services</h2><p>GitHub Pages hosts this site and may keep technical request logs. The page links to YouTube and public archives; their own policies apply when you visit. {a('https://posthog.com/privacy','PostHog privacy')}, {a('https://gumroad.com/privacy','Gumroad privacy')}, {a('https://docs.github.com/en/site-policy/privacy-policies/github-general-privacy-statement','GitHub privacy')}.</p><h2>YouTube API Services</h2><p>Our internal tool “Channels Agent” uses YouTube API Services to publish and measure videos on our own channels only. It does not access a viewer’s account. {a('https://www.youtube.com/t/terms','YouTube terms')}; {a('https://policies.google.com/privacy','Google privacy')}. Access granted to the tool can be revoked at {a('https://myaccount.google.com/permissions','Google account permissions')}.</p><h2>Your choices and retention</h2><p>To see, correct, or delete information we hold, or to stop emails, write to {a('mailto:'+CONTACT,CONTACT)}. We aim to answer within 30 days. Order records are retained as required for accounting; delivery details are used to fulfill and support orders. Browser attribution is limited to the current tab session. Analytics retention follows the configured project’s retention setting; request deletion by contacting us.</p></article>'''
page('/privacy.html','Privacy policy', 'How Make It Do handles free downloads, visit counts, Gumroad checkout, printed orders, and your privacy choices.',privacy)
terms=crumbs([('Terms',None)])+f'''<article class="reading page-intro"><h1>Terms & order information.</h1><p>Make It Do. Updated November 5, 2026.</p><h2>The free material</h2><p>The site, sheets, and cards are for personal and family use. You may print your free sheet and share a link to the site. Our historical data are attributed to their primary sources; government records and archive film may have their own rights statements.</p><h2>The booklet and price</h2><p><cite>Your Year, in Color</cite> is a personalized, 20-page large-print booklet for birth years 1930–1970, with a digital PDF copy. The advertised price is $49 including U.S. shipping. Applicable tax is shown at checkout. It is a one-time purchase, not a subscription. Orders are not open until the checkout is enabled.</p><p>Gumroad is the merchant of record and handles checkout, payment, applicable sales tax, receipts, and refund processing under its terms. We do not take payment on this website. Please check the birth year, cover name, and mailing address before paying.</p><h2>Printing and delivery</h2><p>Printed delivery is offered to U.S. addresses. Production and shipping estimates will be confirmed when ordering opens. No delivery date or holiday arrival is guaranteed here. The digital copy is delivered through Gumroad after payment. No purchase is necessary to download the free sheets.</p><h2>Problems with an order</h2><p>If something we made is wrong or arrives damaged, write to {a('mailto:'+CONTACT,CONTACT)} with your order details. We will work with you to correct the problem. Refunds are handled through Gumroad and the applicable checkout terms; we do not advertise an additional unconditional 30-day refund promise.</p><h2>Historical material</h2><p>Prices are dated U.S. averages, with units and sources provided. They do not represent every store or household. Reference prices are dated, not live. Film images are credited with their actual date, which may differ from the selected birth year. Recreations, if used, are labelled. Historical recipes are source transcriptions and have not been kitchen-tested for this site.</p><h2>Contact</h2><p>{a('mailto:'+CONTACT,CONTACT)}</p></article>'''
page('/terms.html','Terms & order information','Personal use, product details, delivery, Gumroad checkout, damaged orders, and historical source information for Make It Do.',terms)
for alias,target,name in [('/privacy/','/privacy.html','Privacy policy'),('/terms/','/terms.html','Terms & order information')]:
 page(alias,name,'Make It Do '+name.lower()+'.',crumbs([(name,None)])+'<section class="page-intro"><h1>'+name+'</h1>'+a(target,'Read '+name.lower(),'button')+'</section>',noindex=True,canonical=target)
page('/accessibility/','Accessibility statement','Accessibility support and known limits for Make It Do.',crumbs([('Accessibility',None)])+'<article class="reading page-intro"><h1>Accessibility</h1><p>We aim to make this site usable with keyboards, screen readers, and enlarged text, following WCAG 2.2 Level AA. This is a goal, not a certification of conformance.</p><p>Automated checks and keyboard and text enlargement checks are recorded in our launch audit. Automated checks do not cover every disability or assistive technology. Gumroad checkout, confirmation emails, and printed products require separate verification.</p><p>If a page or file is difficult to use, email '+a('mailto:'+CONTACT,CONTACT)+' with the page address and what you need. We will work with you to provide an accessible alternative.</p><p>Reviewed November 7, 2026.</p></article>')
page('/family/','Keepsakes for the whole family','A birth-year keepsake for a parent or the whole family. Start with the Your Year, in Color booklet and a real sample.',crumbs([('The whole family',None)])+'<section class="page-intro reading"><p class="eyebrow">Everybody has a year</p><h1>More than one year.<br><em>One family.</em></h1><p>The first keepsake is the $49 Your Year, in Color booklet. Start with one person’s year and see the real pages before choosing.</p>'+a('/your-year/','See the $49 booklet','button')+'<h2>The larger keepsakes</h2><p>The Family Years is planned at $249 for up to 8 years and 3 hardcover copies. The Heirloom Edition is planned at $1,490 for up to 20 years and 10 cloth hardcovers. These are not available to order yet; samples and final production details must be confirmed first.</p></section>')
page('/thanks/','Your next step','Find your Gumroad receipt and free downloads, or contact Make It Do about an order.',crumbs([('After checkout',None)])+'<section class="page-intro reading"><p class="eyebrow">After your visit to the shop</p><h1>Keep a little<br><em>of the everyday.</em></h1><p>If you completed checkout, your Gumroad receipt contains your download and order details. Visiting this page by itself does not confirm or record a purchase.</p><p>For a printed order, check the year, cover name, and address in your receipt. Questions? '+a('mailto:'+CONTACT,'Email Make It Do')+'.</p>'+a('/year/','Find another free year sheet','button')+'<p>The $29 “other year” add-on is intended for an existing booklet order in the same parcel. It remains unavailable until the order service can confirm eligibility. There is no automatic second charge.</p></section>',noindex=True)
page('/404.html','That page has wandered into another year','Find a free birth-year price sheet or explore Make It Do.', '<section class="page-intro reading"><p class="eyebrow">Page not found</p><h1>Let’s find<br><em>your year.</em></h1>'+yearform(ident='missing-year')+a('/year/','Browse every available year','text-link')+'</section>',noindex=True)
