for door in ['/01/','/01/q/','/01/d/']:
 page(door,'Welcome from the film','Your free birth-year sheet, from the Make It Do film about everyday life in 1950s America.',f'<section class="page-intro reading"><p class="eyebrow">Welcome from the film</p><h1>You’ve seen the world.<br><em>Now find your year.</em></h1><p>From <cite>{C["film_title"]}</cite>.</p>'+yearform(ident='film-year')+'<p>'+a('/kitchen/','Here for the free recipe cards? →','text-link')+'</p><noscript><p>Choose a year in '+a('/year/','the year directory')+' to continue without JavaScript.</p></noscript></section>',noindex=True)
(ROOT/'sitemap.xml').write_text('<?xml version="1.0" encoding="UTF-8"?>\n<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">\n'+''.join(f'<url><loc>{ORIGIN}{p}</loc></url>\n' for p in PAGES)+'</urlset>\n')
